screenPanels.initJs:
function(container, apiUrl, tables) {
  // スライダー値の表示更新
  const sliders = {
    nutrition: container.querySelector('input[name="nutrition"]'),
    cost: container.querySelector('input[name="cost"]'),
    time: container.querySelector('input[name="time"]'),
    preference: container.querySelector('input[name="preference"]')
  };

  const valueDisplays = {
    nutrition: container.querySelector('[data-testid="nutrition-value"]'),
    cost: container.querySelector('[data-testid="cost-value"]'),
    time: container.querySelector('[data-testid="time-value"]'),
    preference: container.querySelector('[data-testid="preference-value"]')
  };

  Object.entries(sliders).forEach(([key, slider]) => {
    slider.addEventListener('input', (e) => {
      valueDisplays[key].textContent = e.target.value + '%';
    });
  });

  // 除外食材・推奨食材の初期化
  const loadItemLists = async () => {
    try {
      const excluded = await window.aivicApi.list(0);
      const recommended = await window.aivicApi.list(1);

      const excludedList = container.querySelector('#excluded-items-list');
      const recommendedList = container.querySelector('#recommended-items-list');

      if (excluded && excluded.length > 0) {
        excludedList.innerHTML = excluded
          .slice(0, 8)
          .map(item => `<div style="padding: 4px 0; border-bottom: 1px solid var(--border);">${item.name || item.ingredient || '食材'}</div>`)
          .join('');
      } else {
        excludedList.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 12px 0;">除外食材がありません</div>';
      }

      if (recommended && recommended.length > 0) {
        recommendedList.innerHTML = recommended
          .slice(0, 8)
          .map(item => `<div style="padding: 4px 0; border-bottom: 1px solid var(--border);">${item.name || item.ingredient || '食材'}</div>`)
          .join('');
      } else {
        recommendedList.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 12px 0;">推奨食材がありません</div>';
      }
    } catch (err) {
      console.error('Failed to load item lists:', err);
    }
  };

  loadItemLists();

  // プレビューボタン
  const previewBtn = container.querySelector('[data-testid="preview-button"]');
  const previewResult = container.querySelector('#preview-result');

  previewBtn.addEventListener('click', () => {
    const algorithm = container.querySelector('[data-testid="algorithm-select"]').value;
    const nutrition = container.querySelector('[data-testid="nutrition-slider"]').value;
    const cost = container.querySelector('[data-testid="cost-slider"]').value;
    const time = container.querySelector('[data-testid="time-slider"]').value;
    const preference = container.querySelector('[data-testid="preference-slider"]').value;
    const learningPeriod = container.querySelector('[data-testid="learning-period-input"]').value;

    if (!algorithm) {
      previewResult.innerHTML = '<div style="color: #ef4444;">アルゴリズムを選択してください</div>';
      return;
    }

    const total = parseInt(nutrition) + parseInt(cost) + parseInt(time) + parseInt(preference);
    const preview = `
      <div style="font-size: 12px; line-height: 1.6;">
        <div><strong>選択アルゴリズム:</strong> ${algorithm}</div>
        <div><strong>優先度配分:</strong> 栄養${nutrition}% / コスト${cost}% / 調理${time}% / 嗜好${preference}%</div>
        <div><strong>学習期間:</strong> ${learningPeriod}日</div>
        <div style="margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border); color: var(--text-muted);">
          ${total === 100 ? '✓ 優先度配分が正常です' : `⚠ 優先度合計: ${total}% (推奨: 100%)`}
        </div>
      </div>
    `;
    previewResult.innerHTML = preview;
  });

  // 更新ボタン
  const updateBtn = container.querySelector('[data-testid="update-button"]');
  const confirmDialog = container.querySelector('#confirm-dialog-overlay');
  const confirmOkBtn = container.querySelector('#confirm-ok-btn');
  const confirmCancelBtn = container.querySelector('#confirm-cancel-btn');
  const successMsg = container.querySelector('#success-message');
  const errorMsg = container.querySelector('#error-message');

  updateBtn.addEventListener('click', () => {
    const algorithm = container.querySelector('[data-testid="algorithm-select"]').value;
    if (!algorithm) {
      errorMsg.textContent = 'アルゴリズムを選択してください';
      errorMsg.style.display = 'block';
      setTimeout(() => { errorMsg.style.display = 'none'; }, 3000);
      return;
    }
    confirmDialog.style.display = 'flex';
  });

  confirmCancelBtn.addEventListener('click', () => {
    confirmDialog.style.display = 'none';
  });

  confirmOkBtn.addEventListener('click', async () => {
    confirmDialog.style.display = 'none';

    const algorithm = container.querySelector('[data-testid="algorithm-select"]').value;
    const nutrition = container.querySelector('[data-testid="nutrition-slider"]').value;
    const cost = container.querySelector('[data-testid="cost-slider"]').value;
    const time = container.querySelector('[data-testid="time-slider"]').value;
    const preference = container.querySelector('[data-testid="preference-slider"]').value;
    const allergySync = container.querySelector('[data-testid="allergy-sync-check"]').checked;
    const restrictionSync = container.querySelector('[data-testid="restriction-sync-check"]').checked;
    const useHistory = container.querySelector('[data-testid="history-toggle"]').checked;
    const learningPeriod = container.querySelector('[data-testid="learning-period-input"]').value;

    try {
      const result = await window.aivicApi.save(0, {
        algorithm,
        nutrition: parseInt(nutrition),
        cost: parseInt(cost),
        time: parseInt(time),
        preference: parseInt(preference),
        allergySync,
        restrictionSync,
        useHistory,
        learningPeriod: parseInt(learningPeriod),
        updatedAt: new Date().toISOString()
      });

      if (result) {
        successMsg.style.display = 'block';
        setTimeout(() => { successMsg.style.display = 'none'; }, 3000);
        previewResult.innerHTML = '<div style="color: #10b981;">✓ アルゴリズムが正常に更新されました</div>';
      }
    } catch (err) {
      console.error('Update failed:', err);
      errorMsg.textContent = 'アルゴリズムの更新に失敗しました';
      errorMsg.style.display = 'block';
      setTimeout(() => { errorMsg.style.display = 'none'; }, 3000);
    }
  });

  // キャンセルボタン
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  cancelBtn.addEventListener('click', () => {
    window.showScreen('scr-1783678463634');
  });

  // 管理画面へのナビゲーション
  container.querySelector('[data-testid="manage-excluded-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1783678285918');
  });

  container.querySelector('[data-testid="manage-recommended-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1783678285918');
  });

  // Escキーでダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && confirmDialog.style.display === 'flex') {
      confirmDialog.style.display = 'none';
    }
  });

  // オーバーレイクリックで閉じる
  confirmDialog.addEventListener('click', (e) => {
    if (e.target === confirmDialog) {
      confirmDialog.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  const startDateInput = container.querySelector('input[name="startDate"]');
  const endDateInput = container.querySelector('input[name="endDate"]');
  const userFilterSelect = container.querySelector('select[name="userId"]');
  const logTypeFilterSelect = container.querySelector('select[name="logType"]');
  const extractButton = container.querySelector('[data-testid="extract-button"]');
  const exportCsvButton = container.querySelector('[data-testid="export-csv-button"]');
  const allergyMgmtButton = container.querySelector('[data-testid="allergy-management-button"]');
  const menuLogMonitoringButton = container.querySelector('[data-testid="menu-log-monitoring-button"]');
  const logListDiv = container.querySelector('#log-list');
  const logDetailDiv = container.querySelector('#log-detail');
  const logDetailModal = container.querySelector('#log-detail-modal');
  const closeLogModalBtn = container.querySelector('#close-log-modal');
  const modalLogContent = container.querySelector('#modal-log-content');

  // KPI 要素
  const totalLogsKpi = container.querySelector('[data-testid="total-logs"]');
  const menuGenerationCountKpi = container.querySelector('[data-testid="menu-generation-count"]');
  const avgRatingKpi = container.querySelector('[data-testid="avg-rating"]');
  const allergyChangesKpi = container.querySelector('[data-testid="allergy-changes"]');

  // Canvas
  const menuFrequencyCanvas = container.querySelector('#menu-frequency-chart');
  const ratingDistributionCanvas = container.querySelector('#rating-distribution-chart');

  // ダミーログデータ（実際は API から取得）
  const mockLogs = [
    { id: 'log-001', timestamp: '2025-01-15 09:30', userId: 'user-001', type: 'menu-generation', description: '献立生成実行', details: '朝食メニュー生成完了。アレルギー情報: なし' },
    { id: 'log-002', timestamp: '2025-01-15 12:15', userId: 'user-002', type: 'meal-rating', description: '食事評価登録', details: '昼食評価: 4.5/5.0 (美味しい)' },
    { id: 'log-003', timestamp: '2025-01-15 14:00', userId: 'user-001', type: 'allergy-history', description: 'アレルギー情報変更', details: 'エビアレルギーを新規追加' },
    { id: 'log-004', timestamp: '2025-01-15 16:45', userId: 'user-003', type: 'restriction-history', description: '食事制限情報変更', details: 'ベジタリアン制限を追加' },
    { id: 'log-005', timestamp: '2025-01-16 08:00', userId: 'user-002', type: 'menu-generation', description: '献立生成実行', details: '朝食メニュー生成完了。食事制限: ベジタリアン' },
    { id: 'log-006', timestamp: '2025-01-16 11:30', userId: 'user-001', type: 'meal-rating', description: '食事評価登録', details: '昼食評価: 3.8/5.0 (普通)' },
  ];

  // 初期化：デフォルト日付を設定
  const today = new Date();
  const sevenDaysAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  startDateInput.valueAsDate = sevenDaysAgo;
  endDateInput.valueAsDate = today;

  // ログ一覧を描画
  function renderLogList(logs) {
    if (logs.length === 0) {
      logListDiv.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 13px;">該当するログがありません</div>';
      return;
    }

    const html = logs.map(log => `
      <div class="log-item" data-id="${log.id}" style="padding: 10px; border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='var(--bg-card)'" onmouseout="this.style.background='transparent'">
        <div style="font-size: 12px; font-weight: 600; color: var(--text);">${log.timestamp}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${log.userId} • ${log.type}</div>
        <div style="font-size: 12px; color: var(--text); margin-top: 4px;">${log.description}</div>
      </div>
    `).join('');

    logListDiv.innerHTML = html;

    // ログアイテムのクリックイベント
    container.querySelectorAll('.log-item').forEach(item => {
      item.addEventListener('click', () => {
        const logId = item.dataset.id;
        const log = logs.find(l => l.id === logId);
        if (log) {
          showLogDetail(log);
        }
      });
    });
  }

  // ログ詳細を表示
  function showLogDetail(log) {
    logDetailDiv.innerHTML = `
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted);">タイムスタンプ</div>
        <div style="font-size: 13px; color: var(--text); margin-top: 2px;">${log.timestamp}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted);">ユーザーID</div>
        <div style="font-size: 13px; color: var(--text); margin-top: 2px;">${log.userId}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted);">ログタイプ</div>
        <div style="font-size: 13px; color: var(--text); margin-top: 2px;">${log.type}</div>
      </div>
      <div style="margin-bottom: 12px;">
        <div style="font-size: 11px; color: var(--text-muted);">説明</div>
        <div style="font-size: 13px; color: var(--text); margin-top: 2px;">${log.description}</div>
      </div>
      <div>
        <div style="font-size: 11px; color: var(--text-muted);">詳細</div>
        <div style="font-size: 13px; color: var(--text); margin-top: 2px;">${log.details}</div>
      </div>
    `;
  }

  // グラフ描画：献立生成頻度（折れ線グラフ）
  function drawMenuFrequencyChart() {
    const ctx = menuFrequencyCanvas.getContext('2d');
    const rect = menuFrequencyCanvas.getBoundingClientRect();
    menuFrequencyCanvas.width = rect.width;
    menuFrequencyCanvas.height = rect.height;

    const data = [2, 3, 2, 4, 3, 5, 4]; // 7日間のデータ
    const labels = ['1/10', '1/11', '1/12', '1/13', '1/14', '1/15', '1/16'];
    const padding = 40;
    const width = menuFrequencyCanvas.width - padding * 2;
    const height = menuFrequencyCanvas.height - padding * 2;
    const maxValue = Math.max(...data);

    // 背景
    ctx.fillStyle = '#faf5f0';
    ctx.fillRect(0, 0, menuFrequencyCanvas.width, menuFrequencyCanvas.height);

    // グリッド
    ctx.strokeStyle = '#e8dfd5';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(menuFrequencyCanvas.width - padding, y);
      ctx.stroke();
    }

    // 折れ線
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((value, index) => {
      const x = padding + (width / (data.length - 1)) * index;
      const y = padding + height - (height / maxValue) * value;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ポイント
    ctx.fillStyle = '#d97706';
    data.forEach((value, index) => {
      const x = padding + (width / (data.length - 1)) * index;
      const y = padding + height - (height / maxValue) * value;
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = '#2d2420';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    labels.forEach((label, index) => {
      const x = padding + (width / (data.length - 1)) * index;
      ctx.fillText(label, x, menuFrequencyCanvas.height - 15);
    });

    // Y軸ラベル
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = padding + (height / 5) * (5 - i);
      ctx.fillText(Math.round((maxValue / 5) * i), padding - 10, y + 4);
    }
  }

  // グラフ描画：食事評価分布（円グラフ）
  function drawRatingDistributionChart() {
    const ctx = ratingDistributionCanvas.getContext('2d');
    const rect = ratingDistributionCanvas.getBoundingClientRect();
    ratingDistributionCanvas.width = rect.width;
    ratingDistributionCanvas.height = rect.height;

    const ratings = { '5.0': 8, '4.0': 12, '3.0': 6, '2.0': 2, '1.0': 1 };
    const colors = ['#d97706', '#f59e0b', '#fbbf24', '#fcd34d', '#fef3c7'];
    const total = Object.values(ratings).reduce((a, b) => a + b, 0);

    const centerX = ratingDistributionCanvas.width / 2;
    const centerY = ratingDistributionCanvas.height / 2;
    const radius = Math.min(centerX, centerY) - 20;

    let currentAngle = -Math.PI / 2;
    let colorIndex = 0;

    Object.entries(ratings).forEach(([rating, count]) => {
      const sliceAngle = (count / total) * Math.PI * 2;

      // スライス
      ctx.fillStyle = colors[colorIndex];
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.lineTo(centerX, centerY);
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);
      ctx.fillStyle = '#2d2420';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(`${rating}`, labelX, labelY);

      currentAngle += sliceAngle;
      colorIndex++;
    });

    // 凡例
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'left';
    let legendY = 20;
    Object.entries(ratings).forEach(([rating, count], idx) => {
      ctx.fillStyle = colors[idx];
      ctx.fillRect(10, legendY, 12, 12);
      ctx.fillStyle = '#2d2420';
      ctx.fillText(`${rating}: ${count}件`, 28, legendY + 6);
      legendY += 18;
    });
  }

  // 抽出実行
  extractButton.addEventListener('click', async () => {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const userId = userFilterSelect.value;
    const logType = logTypeFilterSelect.value;

    // フィルタリング
    let filtered = mockLogs;
    if (userId) filtered = filtered.filter(l => l.userId === userId);
    if (logType) filtered = filtered.filter(l => l.type === logType);

    renderLogList(filtered);

    // KPI 更新
    totalLogsKpi.textContent = filtered.length;
    const menuGenCount = filtered.filter(l => l.type === 'menu-generation').length;
    menuGenerationCountKpi.textContent = menuGenCount;

    const ratings = filtered.filter(l => l.type === 'meal-rating');
    const avgRating = ratings.length > 0 ? (ratings.length * 4.1 / ratings.length).toFixed(1) : '0.0';
    avgRatingKpi.textContent = avgRating;

    const allergyChanges = filtered.filter(l => l.type === 'allergy-history').length;
    allergyChangesKpi.textContent = allergyChanges;

    // グラフ再描画
    drawMenuFrequencyChart();
    drawRatingDistributionChart();
  });

  // CSV エクスポート
  exportCsvButton.addEventListener('click', () => {
    const logs = mockLogs;
    const headers = ['タイムスタンプ', 'ユーザーID', 'ログタイプ', '説明', '詳細'];
    const rows = logs.map(l => [l.timestamp, l.userId, l.type, l.description, l.details]);

    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => r.map(cell => `"${cell}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'app-logs.csv';
    link.click();
  });

  // ナビゲーション
  allergyMgmtButton.addEventListener('click', () => {
    window.showScreen('scr-1783678285918');
  });

  menuLogMonitoringButton.addEventListener('click', () => {
    window.showScreen('scr-1783678313897');
  });

  // モーダル閉じる
  closeLogModalBtn.addEventListener('click', () => {
    logDetailModal.style.display = 'none';
  });

  logDetailModal.addEventListener('click', (e) => {
    if (e.target === logDetailModal) {
      logDetailModal.style.display = 'none';
    }
  });

  // 初期表示
  renderLogList(mockLogs);
  drawMenuFrequencyChart();
  drawRatingDistributionChart();

  // KPI 初期化
  totalLogsKpi.textContent = mockLogs.length;
  menuGenerationCountKpi.textContent = mockLogs.filter(l => l.type === 'menu-generation').length;
  avgRatingKpi.textContent = '4.1';
  allergyChangesKpi.textContent = mockLogs.filter(l => l.type === 'allergy-history').length;
}

function(container, apiUrl, tables) {
  const form = container.querySelector('#priority-form');
  const tbody = container.querySelector('#priority-tbody');
  const confirmModal = container.querySelector('#confirm-modal');
  const confirmMessage = container.querySelector('#confirm-message');
  const confirmCancel = container.querySelector('#confirm-cancel');
  const confirmOk = container.querySelector('#confirm-ok');
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  const testBtn = container.querySelector('[data-testid="test-delivery-button"]');
  const nextDeliveryEl = container.querySelector('#next-delivery');
  const deliveredCountEl = container.querySelector('#delivered-count');
  const activeRulesCountEl = container.querySelector('#active-rules-count');

  let currentEditId = null;
  let pendingAction = null;

  // Load priority rules
  async function loadRules() {
    const rules = await window.aivicApi.list(0);
    if (!rules) return;

    tbody.innerHTML = '';
    rules.forEach(rule => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.dataset.id = rule.id;
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${rule.ruleName || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${rule.priorityLevel || '-'}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="edit-btn" data-id="${rule.id}" style="padding: 4px 8px; background: transparent; color: var(--primary); border: none; font-size: 12px; cursor: pointer; margin-right: 4px;">編集</button>
          <button class="delete-btn" data-id="${rule.id}" style="padding: 4px 8px; background: transparent; color: #d97706; border: none; font-size: 12px; cursor: pointer;">削除</button>
        </td>
      `;
      tbody.appendChild(tr);
    });

    activeRulesCountEl.textContent = rules.length;
  }

  // Save rule
  saveBtn.addEventListener('click', async () => {
    const formData = new FormData(form);
    const channels = Array.from(form.querySelectorAll('input[name="channel"]:checked')).map(el => el.value);

    const ruleData = {
      ruleName: formData.get('ruleName'),
      priorityLevel: formData.get('priorityLevel'),
      nutritionCategory: formData.get('nutritionCategory'),
      importanceScore: parseInt(formData.get('importanceScore')) || 0,
      targetUsers: formData.getAll('targetUsers'),
      channels: channels,
      deliveryTiming: formData.get('deliveryTiming'),
      template: formData.get('template'),
      conditionalRules: formData.get('conditionalRules'),
    };

    if (!ruleData.ruleName || !ruleData.priorityLevel) {
      alert('ルール名と優先度レベルは必須です');
      return;
    }

    if (currentEditId) {
      await window.aivicApi.update(0, currentEditId, ruleData);
    } else {
      await window.aivicApi.save(0, ruleData);
    }

    form.reset();
    currentEditId = null;
    loadRules();
  });

  // Edit rule
  tbody.addEventListener('click', async (e) => {
    if (e.target.classList.contains('edit-btn')) {
      const id = e.target.dataset.id;
      const rules = await window.aivicApi.list(0);
      const rule = rules.find(r => r.id === id);

      if (rule) {
        form.querySelector('[data-testid="rule-name"]').value = rule.ruleName || '';
        form.querySelector('[data-testid="priority-level"]').value = rule.priorityLevel || '';
        form.querySelector('[data-testid="nutrition-category"]').value = rule.nutritionCategory || '';
        form.querySelector('[data-testid="importance-score"]').value = rule.importanceScore || '';
        form.querySelector('[data-testid="delivery-timing"]').value = rule.deliveryTiming || '';
        form.querySelector('[data-testid="template-select"]').value = rule.template || '';
        form.querySelector('[data-testid="conditional-rules"]').value = rule.conditionalRules || '';

        if (rule.channels) {
          form.querySelectorAll('input[name="channel"]').forEach(el => {
            el.checked = rule.channels.includes(el.value);
          });
        }

        currentEditId = id;
        saveBtn.textContent = '更新';
      }
    } else if (e.target.classList.contains('delete-btn')) {
      const id = e.target.dataset.id;
      pendingAction = { type: 'delete', id };
      confirmMessage.textContent = 'このルールを削除しますか？';
      confirmModal.style.display = 'flex';
    }
  });

  // Test delivery
  testBtn.addEventListener('click', () => {
    const ruleName = form.querySelector('[data-testid="rule-name"]').value;
    if (!ruleName) {
      alert('ルール名を入力してください');
      return;
    }
    pendingAction = { type: 'test' };
    confirmMessage.textContent = `「${ruleName}」のテスト配信を実行しますか？`;
    confirmModal.style.display = 'flex';
  });

  // Confirm modal handlers
  confirmCancel.addEventListener('click', () => {
    confirmModal.style.display = 'none';
    pendingAction = null;
  });

  confirmOk.addEventListener('click', async () => {
    if (pendingAction.type === 'delete') {
      await window.aivicApi.delete(0, pendingAction.id);
      loadRules();
    } else if (pendingAction.type === 'test') {
      alert('テスト配信を実行しました');
      deliveredCountEl.textContent = parseInt(deliveredCountEl.textContent) + 1;
    }
    confirmModal.style.display = 'none';
    pendingAction = null;
  });

  // Close modal on backdrop click
  confirmModal.addEventListener('click', (e) => {
    if (e.target === confirmModal) {
      confirmModal.style.display = 'none';
      pendingAction = null;
    }
  });

  // Initialize
  loadRules();
  nextDeliveryEl.textContent = new Date(Date.now() + 86400000).toLocaleDateString('ja-JP');
}

function(container, apiUrl, tables) {
  const tableIndex = 0;
  let datasources = [];
  let selectedId = null;
  let editingId = null;

  // DOM 要素取得
  const listContainer = container.querySelector('#datasource-list');
  const detailPanel = container.querySelector('#detail-panel');
  const addBtn = container.querySelector('[data-testid="add-datasource-btn"]');
  const dsModal = container.querySelector('#datasource-modal');
  const deleteModal = container.querySelector('#delete-modal');
  const syncModal = container.querySelector('#sync-modal');
  const modalTitle = container.querySelector('#modal-title');
  const dsNameInput = container.querySelector('#ds-name');
  const dsTypeInput = container.querySelector('#ds-type');
  const dsEndpointInput = container.querySelector('#ds-endpoint');
  const dsApikeyInput = container.querySelector('#ds-apikey');
  const dsScheduleInput = container.querySelector('#ds-schedule');
  const dsFilterInput = container.querySelector('#ds-filter');
  const dsMappingInput = container.querySelector('#ds-mapping');
  const modalSaveBtn = container.querySelector('[data-testid="modal-save-btn"]');
  const modalCancelBtn = container.querySelector('[data-testid="modal-cancel-btn"]');
  const deleteCancelBtn = container.querySelector('[data-testid="delete-cancel-btn"]');
  const deleteConfirmBtn = container.querySelector('#delete-confirm-btn');
  const syncCancelBtn = container.querySelector('[data-testid="sync-cancel-btn"]');
  const syncConfirmBtn = container.querySelector('#sync-confirm-btn');

  // データ取得
  async function loadDatasources() {
    const rows = await window.aivicApi.list(tableIndex);
    datasources = rows || [];
    renderList();
  }

  // 一覧レンダリング
  function renderList() {
    listContainer.innerHTML = '';
    datasources.forEach(ds => {
      const item = document.createElement('div');
      item.className = 'datasource-item';
      item.dataset.id = ds.id;
      item.style.cssText = `
        padding: 10px 12px;
        border-bottom: 1px solid var(--border);
        cursor: pointer;
        transition: background 0.2s;
        background: ${selectedId === ds.id ? 'var(--bg-main)' : 'transparent'};
      `;

      const statusColor = ds.status === 'connected' ? '#10b981' : ds.status === 'error' ? '#ef4444' : '#f59e0b';
      const statusLabel = ds.status === 'connected' ? '接続中' : ds.status === 'error' ? 'エラー' : '未接続';

      item.innerHTML = `
        <div style="display: flex; align-items: flex-start; gap: 8px;">
          <div style="width: 8px; height: 8px; border-radius: 50%; background: ${statusColor}; margin-top: 4px; flex-shrink: 0;"></div>
          <div style="flex: 1; min-width: 0;">
            <div style="font-size: 13px; font-weight: 500; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${ds.name || '（無名）'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${ds.type || 'API'}</div>
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${statusLabel}</div>
          </div>
        </div>
      `;

      item.addEventListener('click', () => selectDatasource(ds.id));
      listContainer.appendChild(item);
    });
  }

  // データソース選択
  function selectDatasource(id) {
    selectedId = id;
    editingId = null;
    renderList();
    renderDetail();
  }

  // 詳細パネルレンダリング
  function renderDetail() {
    if (!selectedId) {
      detailPanel.innerHTML = `
        <div style="flex: 1; display: flex; align-items: center; justify-content: center; color: var(--text-muted); font-size: 14px;">
          <div style="text-align: center;">
            <div style="margin-bottom: 8px;">📋</div>
            <div>データソースを選択してください</div>
          </div>
        </div>
      `;
      return;
    }

    const ds = datasources.find(d => d.id === selectedId);
    if (!ds) return;

    const lastSync = ds.lastSyncTime ? new Date(ds.lastSyncTime).toLocaleString('ja-JP') : '未実行';
    const syncStatus = ds.syncStatus || '待機中';

    detailPanel.innerHTML = `
      <div style="padding: 16px; display: flex; flex-direction: column; gap: 16px; overflow-y: auto;">
        <!-- ヘッダー -->
        <div>
          <div style="font-size: 14px; font-weight: 600; color: var(--text); margin-bottom: 8px;">${ds.name}</div>
          <div style="display: flex; gap: 8px; flex-wrap: wrap;">
            <span style="font-size: 11px; background: var(--bg-main); color: var(--text); padding: 4px 8px; border-radius: 3px;">${ds.type || 'API'}</span>
            <span style="font-size: 11px; background: var(--bg-main); color: var(--text); padding: 4px 8px; border-radius: 3px;">${ds.status === 'connected' ? '✓ 接続中' : ds.status === 'error' ? '✗ エラー' : '○ 未接続'}</span>
          </div>
        </div>

        <!-- 同期情報 -->
        <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border-left: 3px solid var(--primary);">
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px;">最終同期</div>
          <div style="font-size: 13px; color: var(--text); margin-bottom: 8px;">${lastSync}</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 4px;">ステータス</div>
          <div style="font-size: 13px; color: var(--text);">${syncStatus}</div>
        </div>

        <!-- 接続情報 -->
        <div>
          <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">接続情報</div>
          <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; font-size: 12px; color: var(--text); font-family: monospace; word-break: break-all;">
            ${ds.endpoint || '（未設定）'}
          </div>
        </div>

        <!-- スケジュール -->
        <div>
          <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 4px;">同期スケジュール</div>
          <div style="font-size: 13px; color: var(--text);">${ds.schedule === 'manual' ? '手動' : ds.schedule === 'hourly' ? '1 時間ごと' : ds.schedule === 'daily' ? '1 日 1 回' : ds.schedule === 'weekly' ? '週 1 回' : '未設定'}</div>
        </div>

        <!-- アクション -->
        <div style="display: flex; gap: 8px; margin-top: 8px;">
          <button class="action-btn" data-testid="sync-btn" style="flex: 1; padding: 8px 12px; font-size: 13px;">🔄 同期実行</button>
          <button class="action-btn secondary" data-testid="edit-btn" style="flex: 1; padding: 8px 12px; font-size: 13px;">✏️ 編集</button>
          <button class="action-btn secondary" data-testid="delete-btn" style="flex: 1; padding: 8px 12px; font-size: 13px;">🗑️ 削除</button>
        </div>

        <!-- 詳細情報 -->
        <div style="border-top: 1px solid var(--border); padding-top: 12px;">
          <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 8px;">詳細設定</div>
          <div style="display: flex; flex-direction: column; gap: 8px; font-size: 12px;">
            <div>
              <div style="color: var(--text-muted); margin-bottom: 2px;">フィルタ条件</div>
              <div style="background: var(--bg-main); padding: 8px; border-radius: 3px; color: var(--text); font-family: monospace; word-break: break-all; max-height: 80px; overflow-y: auto;">
                ${ds.filter ? JSON.stringify(JSON.parse(ds.filter), null, 2) : '（なし）'}
              </div>
            </div>
            <div>
              <div style="color: var(--text-muted); margin-bottom: 2px;">データマッピング</div>
              <div style="background: var(--bg-main); padding: 8px; border-radius: 3px; color: var(--text); font-family: monospace; word-break: break-all; max-height: 80px; overflow-y: auto;">
                ${ds.mapping ? JSON.stringify(JSON.parse(ds.mapping), null, 2) : '（なし）'}
              </div>
            </div>
          </div>
        </div>
      </div>
    `;

    // イベントリスナー
    detailPanel.querySelector('[data-testid="sync-btn"]').addEventListener('click', () => openSyncModal(ds));
    detailPanel.querySelector('[data-testid="edit-btn"]').addEventListener('click', () => openEditModal(ds));
    detailPanel.querySelector('[data-testid="delete-btn"]').addEventListener('click', () => openDeleteModal(ds));
  }

  // モーダル: 追加
  function openAddModal() {
    editingId = null;
    modalTitle.textContent = '新規データソース追加';
    dsNameInput.value = '';
    dsTypeInput.value = '';
    dsEndpointInput.value = '';
    dsApikeyInput.value = '';
    dsScheduleInput.value = 'manual';
    dsFilterInput.value = '';
    dsMappingInput.value = '';
    dsModal.style.display = 'flex';
  }

  // モーダル: 編集
  function openEditModal(ds) {
    editingId = ds.id;
    modalTitle.textContent = 'データソース編集';
    dsNameInput.value = ds.name || '';
    dsTypeInput.value = ds.type || '';
    dsEndpointInput.value = ds.endpoint || '';
    dsApikeyInput.value = ds.apikey || '';
    dsScheduleInput.value = ds.schedule || 'manual';
    dsFilterInput.value = ds.filter || '';
    dsMappingInput.value = ds.mapping || '';
    dsModal.style.display = 'flex';
  }

  // モーダル: 削除確認
  function openDeleteModal(ds) {
    deleteModal.style.display = 'flex';
    deleteConfirmBtn.onclick = async () => {
      await window.aivicApi.delete(tableIndex, ds.id);
      deleteModal.style.display = 'none';
      selectedId = null;
      await loadDatasources();
    };
  }

  // モーダル: 同期実行確認
  function openSyncModal(ds) {
    container.querySelector('#sync-datasource-name').textContent = `「${ds.name}」を同期します`;
    syncModal.style.display = 'flex';
    syncConfirmBtn.onclick = async () => {
      syncModal.style.display = 'none';
      // 同期実行（実装例）
      const updated = await window.aivicApi.update(tableIndex, ds.id, {
        syncStatus: '同期中...',
        lastSyncTime: new Date().toISOString()
      });
      if (updated) {
        await loadDatasources();
        selectDatasource(ds.id);
      }
    };
  }

  // モーダル: 保存
  modalSaveBtn.addEventListener('click', async () => {
    const payload = {
      name: dsNameInput.value,
      type: dsTypeInput.value,
      endpoint: dsEndpointInput.value,
      apikey: dsApikeyInput.value,
      schedule: dsScheduleInput.value,
      filter: dsFilterInput.value,
      mapping: dsMappingInput.value,
      status: 'connected',
      syncStatus: '待機中'
    };

    let result;
    if (editingId) {
      result = await window.aivicApi.update(tableIndex, editingId, payload);
    } else {
      result = await window.aivicApi.save(tableIndex, payload);
    }

    if (result) {
      dsModal.style.display = 'none';
      await loadDatasources();
      if (result.id) selectDatasource(result.id);
    }
  });

  // モーダル: キャンセル
  modalCancelBtn.addEventListener('click', () => {
    dsModal.style.display = 'none';
  });
  deleteCancelBtn.addEventListener('click', () => {
    deleteModal.style.display = 'none';
  });
  syncCancelBtn.addEventListener('click', () => {
    syncModal.style.display = 'none';
  });

  // ボタンイベント
  addBtn.addEventListener('click', openAddModal);

  // Esc キーでモーダル閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      dsModal.style.display = 'none';
      deleteModal.style.display = 'none';
      syncModal.style.display = 'none';
    }
  });

  // overlay クリックで閉じる
  dsModal.addEventListener('click', (e) => {
    if (e.target === dsModal) dsModal.style.display = 'none';
  });
  deleteModal.addEventListener('click', (e) => {
    if (e.target === deleteModal) deleteModal.style.display = 'none';
  });
  syncModal.addEventListener('click', (e) => {
    if (e.target === syncModal) syncModal.style.display = 'none';
  });

  // 初期化
  loadDatasources();
}
